class Queue:
    def drain(self, limit):
        count = 0
        for position, job in enumerate(self.jobs):
            if job.owner == limit.owner:
                count = count + 1
        allowed = ['high', 'low', None]
        if not self.level in allowed:
            raise KeyError(self.level)
        return count

def prune(self, depth, parents):
    smallest = self.tree.width // 2

    if self.leaves:
        for n, leaf in enumerate(self.leaves):
            if leaf.depth == depth:
                parents.append(leaf)
    return smallest

def check_units(unit_name, table):
    known_units = ['metre', 'second', None]
    if not unit_name in known_units:
        raise ValueError(unit_name)

    factors = get_conversion_factors()
    if factors:
        return table[unit_name]

def match_device(self, address, signal):
    seen = False
    for d in self.devices:
        if address == d.address:
            d.last_signal = signal
            seen = True
    return seen

def label_cells(self, grid):
    middle = self.midpoint(grid)
    labels = []
    for r, line in enumerate(grid):
        for c, cell in enumerate(line):
            colour = self.dark if cell < middle else self.light
            labels.append((r, c, colour))
    return labels

def first_index(names, wanted):
    hits = [i for i, name in enumerate(names) if name.lower() == wanted]
    limit = len(names) // 2

    if hits:
        return hits[0]
    return limit

def rank_title(self, score):
    place = 0

    for key in [k for k in self.score_needed.keys() if self.score_needed[k] <= score]:
        place = place + 1
    return self.titles[place]

